    });
  });
  drawBars('params');

  /* ---------- 02 grammar ---------- */
  var CALL=[
    ['{&quot;name&quot;:&quot;',1],['set_lights',0],['&quot;,&quot;arguments&quot;:{&quot;room&quot;:&quot;',1],['living room',0],
    ['&quot;,&quot;on&quot;:',1],['true',0],[',&quot;brightness&quot;:',1],['30',0],['}}',1]
  ];
  var term=document.getElementById('n2-term'), m1=document.getElementById('n2-m1'), m2=document.getElementById('n2-m2');
  var timer=null;
  function resetG(){
